import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import DataTable from 'datatables.net-react';
import DT from 'datatables.net-dt';
import 'datatables.net-dt/css/dataTables.dataTables.css';

DataTable.use(DT);

const MostLikelyDetailsPage = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { mostLikelyData } = location.state || {};

  const formatCurrency = (value) =>
    new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(value ?? 0);

  const initialRows = (mostLikelyData?.details ?? []).map((row) => {
    const confidence = row.confidencePercent ?? 80;
    const baseRevenue = row.monthRevenue ?? 0;
    const updatedRevenue = (baseRevenue * confidence) / 100;
    const prevRevenue = row.prevMonthRevenue ?? 0;

    return {
      ...row,
      confidencePercent: confidence,
      baseMonthRevenue: baseRevenue,
      monthRevenue: formatCurrency(updatedRevenue),
      prevMonthRevenue: formatCurrency(prevRevenue),
      variance: formatCurrency(updatedRevenue - prevRevenue),
      varianceReason: row.varianceReason ?? '',
    };
  });

  const [rows, setRows] = useState(initialRows);

  const handleConfidenceChange = (index, value) => {
    let percent = parseFloat(value);
    if (isNaN(percent)) percent = 0;
    if (percent < 0) percent = 0;
    if (percent > 100) percent = 100;

    setRows((prev) => {
      const updated = [...prev];
      const r = { ...updated[index] };
      r.confidencePercent = percent;
      const updatedRevenue = (r.baseMonthRevenue * percent) / 100;
      r.monthRevenue = formatCurrency(updatedRevenue);
      r.variance = formatCurrency(updatedRevenue - (r.prevMonthRevenueRaw ?? 0));
      updated[index] = r;
      return updated;
    });
  };

  const handleReasonChange = (index, value) => {
    setRows((prev) => {
      const updated = [...prev];
      updated[index].varianceReason = value;
      return updated;
    });
  };

  const columns = [
    { title: 'Associate ID', data: 'associateId' },
    { title: 'Name', data: 'name' },
    { title: 'Service Line', data: 'serviceLine' },
    { title: 'Project ID', data: 'projectId' },
    { title: 'Project Name', data: 'projectName' },
    { title: 'Start Date', data: 'startDate' },
    { title: 'End Date', data: 'endDate' },
    { title: 'Current Start', data: 'currentStartDate' },
    { title: 'Current End', data: 'currentEndDate' },
    { title: 'Billability', data: 'billabilityType' },
    { title: 'City', data: 'city' },
    { title: 'State', data: 'state' },
    { title: 'Rate', data: 'rate' },
    { title: 'Hours', data: 'hours' },
    { title: 'Month Hours', data: 'monthHours' },
    { title: 'Month Revenue', data: 'monthRevenue' },
    {
      title: 'Confidence %',
      data: 'confidencePercent',
      render: (data, type, row, meta) => {
        if (type === 'display') {
          return `<input type="number" min="0" max="100" value="${data}" style="width: 80px;" data-row-index="${meta.row}" class="confidence-input" />`;
        }
        return data;
      },
    },
    { title: 'Prev Revenue', data: 'prevMonthRevenue' },
    { title: 'Variance', data: 'variance' },
    {
      title: 'Reason',
      data: 'varianceReason',
      render: (data, type, row, meta) => {
        if (type === 'display') {
          return `
            <select class="reason-dropdown" data-row-index="${meta.row}">
              <option value="">Select</option>
              <option value="Scope Change"${data === 'Scope Change' ? ' selected' : ''}>Scope Change</option>
              <option value="Rate Update"${data === 'Rate Update' ? ' selected' : ''}>Rate Update</option>
              <option value="Manual Override"${data === 'Manual Override' ? ' selected' : ''}>Manual Override</option>
              <option value="Other"${data === 'Other' ? ' selected' : ''}>Other</option>
            </select>
            <input type="text" class="reason-text" value="${data}" data-row-index="${meta.row}" placeholder="Or type reason" />
          `;
        }
        return data;
      },
    },
  ];

  const noData = !mostLikelyData || !mostLikelyData.details;

  return (
    <div className="details-page">
      <button onClick={() => navigate('/')}>Back to Dashboard</button>
      <h2>Most Likely Details</h2>
      {noData ? (
        <p>No Most Likely data available. Please go back to the dashboard.</p>
      ) : (
        <DataTable
          columns={columns}
          data={rows}
          options={{
            paging: true,
            searching: true,
            info: true,
            createdRow: (row, data, dataIndex) => {
              const input = row.querySelector('input.confidence-input');
              if (input) {
                input.addEventListener('change', (e) => {
                  handleConfidenceChange(dataIndex, e.target.value);
                });
              }

              const dropdown = row.querySelector('select.reason-dropdown');
              const textInput = row.querySelector('input.reason-text');
              if (dropdown) {
                dropdown.addEventListener('change', (e) => {
                  handleReasonChange(dataIndex, e.target.value);
                });
              }
              if (textInput) {
                textInput.addEventListener('input', (e) => {
                  handleReasonChange(dataIndex, e.target.value);
                });
              }
            },
          }}
        />
      )}
    </div>
  );
};

export default MostLikelyDetailsPage;
